const { accessSync, constants } = await import('node:fs');
const input = process.env.INPUT_HTML;
const output = process.env.OUTPUT_PDF;
if (!input || !output) throw new Error('Missing required inputs');
try { accessSync(input, constants.R_OK); } catch { throw new Error('Input file not accessible'); }
globalThis.inputPath = input;
globalThis.outputPath = output;

const { execFileSync } = await import('node:child_process');
const { join } = await import('node:path');
const pkgPath = join(process.cwd(), 'node_modules', '@aspirio', 'topdf', 'index.js');
execFileSync('node', [pkgPath, '-i', globalThis.inputPath, '-o', globalThis.outputPath]);
globalThis.resultPath = globalThis.outputPath;
